head.script:
scwin.onpageload = function () {
    dlt_a.setJSON([
        { "name" : "홍길동", "city" : "S" },
        { "name" : "김철수", "city" : "B" },
        { "name" : "이영희", "city" : "D" }
    ]);
};

// [A] 편집 종료 시 Cell 값 출력
scwin.grd_a_onafteredit = function (rowIndex, colIndex, value) {
    if (grd_a.getColumnID(colIndex) !== "city") {
        return;
    }
    scwin.setReturnValue("[A] " + dlt_a.getCellData(rowIndex, "name") + " 행 city 편집 종료 : Cell 값 '" + dlt_a.getCellData(rowIndex, "city") + "' (표시 '" + grd_a.getCellDisplayData(rowIndex, "city") + "')");
};

// [B] 값 변경 시 출력 (Enter 로는 발생하지 않아야 함)
scwin.acb_b_onviewchange = function (info) {
    scwin.setReturnValue("[B] 값 확정 : '" + acb_b.getValue() + "' (표시 '" + acb_b.getText() + "')");
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
